function (specs, calendar, call = caller_env()) 
{
    granules <- list(pane_default = FALSE)
    for (arg in names(specs)) {
        spec <- specs[[arg]]
        resolved <- if (is.null(spec$unit)) {
            eval_granule(spec$quo, calendar, arg = arg, call = call)
        }
        else {
            eval_granule_default(spec$quo, spec$is_default, spec$unit, 
                spec$fallback, calendar, arg = arg, call = call)
        }
        granules[arg] <- list(resolved)
        if (!is.null(spec$default)) {
            granules$pane_default <- identical(resolved, eval_granule(spec$default, 
                calendar, arg = arg, call = call))
        }
    }
    granules
}
