function (quo, calendar, arg = "x", call = caller_env()) 
{
    x <- tryCatch(eval_tidy(quo, data = calendar, env = emptyenv()), 
        error = function(e) {
            unit <- sub("^could not find function \"(.*)\"$", 
                "\\1", conditionMessage(e))
            if (!identical(unit, conditionMessage(e))) {
                cli::cli_abort(c(conditionMessage(e), i = "This calendar has no {.val {unit}} granule.", 
                  i = "Granule tokens are resolved against the calendar of the time\n                 axis's data; supply the granule explicitly (e.g.\n                 {.code mixtime::cal_isoweek${unit}(1L)}), or use a duration\n                 instead."), 
                  call = call)
            }
            cli::cli_abort(conditionMessage(e), call = call)
        })
    duration_as_granule(x, arg = arg, call = call)
}
