function (quo, is_default, unit, fallback, calendar, arg = "x", 
    call = caller_env()) 
{
    if (is_default && !(unit %in% names(calendar))) {
        quo <- fallback
    }
    eval_granule(quo, calendar, arg = arg, call = call)
}
